<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Maintenance service | Triple R Gensan</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/staff">Triple R Gensan</a><nav class="staff-actions"><a href="/maintenance">Maintenance</a><a href="/fleet/vehicles">Fleet</a></nav></header><main class="page-shell">
<?php if(!empty($notice)):?><p class="notice panel"><?= $e($notice) ?></p><?php endif;?>
<?php if($service===null):?><section class="page-heading"><div><p class="eyebrow">New maintenance record</p><h1>Start service</h1><p>Vehicle will remain unavailable while the service is in progress.</p></div></section><section class="panel"><form method="post" action="/maintenance/service/start"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><label>Vehicle<select name="vehicle_id" id="maintenance-vehicle" required><option value="">Choose vehicle</option><?php foreach($vehicles as $v):?><option value="<?= (int)$v['vehicle_id'] ?>"<?= $vehicle&& (int)$vehicle['vehicle_id']===(int)$v['vehicle_id']?' selected':'' ?>><?= $e($v['plate_number'].' '.$v['make'].' '.$v['model'].' — '.$v['current_status']) ?></option><?php endforeach;?></select></label><p>Select a vehicle, then start to record its existing status and mileage lock.</p><label>Named schedule (optional)<select name="schedule_id"><option value="">Unscheduled corrective work</option><?php foreach($schedules as $s):?><option value="<?= (int)$s['schedule_id'] ?>"><?= $e($s['plate_number'].' · '.$s['schedule_name']) ?></option><?php endforeach;?></select></label><label>Service title<input name="title" maxlength="160" required placeholder="Oil and filter change"></label><label>Notes<textarea name="notes" maxlength="2000"></textarea></label><button>Start service</button></form><p>The service start is blocked for vehicles with an active rental, unexpired hold, or incompatible status. A selected schedule must belong to the chosen vehicle.</p></section>
<?php else:?><section class="page-heading"><div><p class="eyebrow">Service #<?= (int)$service['service_id'] ?> · <?= $e($service['status']) ?></p><h1><?= $e($service['title']) ?></h1><p><?= $e($service['plate_number'].' '.$service['make'].' '.$service['model']) ?> · <?= $e($service['schedule_name']??'Unscheduled corrective work') ?> · mechanic <?= $e($service['mechanic_name']) ?></p></div><a class="button-link" href="/maintenance/history?vehicle_id=<?= (int)$service['vehicle_id'] ?>">Vehicle history</a></section>
<section class="panel"><p>Status before service: <strong><?= $e($service['vehicle_status_before']) ?></strong>. Started <?= $e($service['started_at']) ?>. Current service status: <?= $e($service['status']) ?>.<?php if((int)$service['needs_review']===1):?> <strong>Manager review required; vehicle remains in maintenance.</strong><?php endif;?></p><?php if($service['notes']):?><p><?= nl2br($e($service['notes'])) ?></p><?php endif;?><?php if($canOperate&&$service['status']==='in_progress'):?><form method="post" action="/maintenance/service/complete"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="service_id" value="<?= (int)$service['service_id'] ?>"><label>Completion odometer (km)<input type="number" name="mileage" min="0" max="4294967295" required></label><button>Complete service</button></form><form method="post" action="/maintenance/service/cancel"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="service_id" value="<?= (int)$service['service_id'] ?>"><label>Cancellation reason<input name="reason" maxlength="500" required></label><button>Cancel service</button></form><?php endif;?></section>
<section class="panel"><h2>Service costs</h2><p>Labor <?= $e($service['labor_cost']) ?> · Parts <?= $e($service['parts_cost']) ?> · Other <?= $e($service['other_cost']) ?> · Generated total <strong><?= $e($service['total_cost']) ?></strong></p><?php if($canOperate&&$service['status']!=='cancelled'&&($service['status']==='in_progress'||$canManage)):?><form method="post" action="/maintenance/service/costs"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="service_id" value="<?= (int)$service['service_id'] ?>"><label>Labor cost<input name="labor_cost" type="number" min="0" step="0.01" value="<?= $e($service['labor_cost']) ?>" required></label><label>Parts cost<input name="parts_cost" type="number" min="0" step="0.01" value="<?= $e($service['parts_cost']) ?>" required></label><label>Other cost<input name="other_cost" type="number" min="0" step="0.01" value="<?= $e($service['other_cost']) ?>" required></label><label>Reason<input name="reason" maxlength="500" required></label><button>Save costs</button></form><?php endif;?><?php if($audits):?><h3>Cost change audit</h3><?php foreach($audits as $a):?><p><?= $e($a['created_at'].' · '.$a['actor_name'].' · '.$a['reason']) ?> — <?= $e($a['old_labor_cost'].'/'.$a['old_parts_cost'].'/'.$a['old_other_cost']) ?> → <?= $e($a['new_labor_cost'].'/'.$a['new_parts_cost'].'/'.$a['new_other_cost']) ?></p><?php endforeach;?><?php endif;?></section>
<section class="panel"><h2>Photo evidence</h2><?php if($canOperate&&$service['status']==='in_progress'):?><form method="post" action="/maintenance/service/photo" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="service_id" value="<?= (int)$service['service_id'] ?>"><input type="hidden" name="phase" value="before"><label>Before-service photo<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></label><button>Upload before photo</button></form><?php endif;?><?php if($canOperate&&$service['status']==='completed'):?><form method="post" action="/maintenance/service/photo" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="service_id" value="<?= (int)$service['service_id'] ?>"><input type="hidden" name="phase" value="after"><label>After-service photo<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></label><button>Upload after photo</button></form><?php endif;?><?php if(!$photos):?><p>No photos attached.</p><?php else:?><ul><?php foreach($photos as $p):?><li><?= $e($p['phase'].' · '.$p['original_filename']) ?> — <a href="/maintenance/photo?photo_id=<?= (int)$p['photo_id'] ?>" target="_blank" rel="noopener">View private photo</a></li><?php endforeach;?></ul><?php endif;?></section>
<?php endif;?></main></body></html>
